 return '<div class="card" data-open="'+p._id+'" role="button" tabindex="0" data-cursor="off" style="--cc:'+col+';--ccg:'+hx(col,0.5)+'"><div class="thumb">'+thumb+'<span class="rp-badge">Package</span></div><div class="body"><h3>'+esc(p.name)+'</h3>'
